import { BookOpen, ChevronDown, ChevronLeft, ChevronRight, ChevronUp, Eye, EyeOff, Focus, GripVertical, Layers3, Maximize, Minimize, Pause, Play, RotateCcw, RotateCw, Search, X } from 'lucide-react';
import { useCallback, useEffect, useMemo, useReducer, useRef, useState } from 'react';
import { useLocation, useNavigate, useParams } from 'react-router-dom';
import { useMuseumConfig } from '../../config/ConfigProvider';
import { resolveAssetUrl } from '../../config/loadConfig';
import type { DeviceConfig } from '../../config/schema';
import { useCameFrom } from '../../shared/back';
import { useFullscreen } from '../../shared/fullscreen';
import { hasWebGLSupport } from '../../shared/webgl';
import { ResourceDrawer } from '../archive/ResourceDrawer';
import { createDeviceExplorerState, deviceExplorerReducer } from './deviceExplorerState';
import { DeviceScene, type DeviceSceneComponent } from './DeviceScene';
import type { DeviceView } from './useDeviceView';
import './device.css';

const VIEWS: Array<{ id: DeviceView; short: string; label: string }> = [
  { id: 'three-quarter', short: '轴', label: '轴测视图' },
  { id: 'front', short: '前', label: '前视图' },
  { id: 'side', short: '侧', label: '侧视图' },
  { id: 'back', short: '后', label: '后视图' },
];

export interface DevicePageProps {
  SceneComponent?: DeviceSceneComponent;
  supportsWebGL?: () => boolean;
  disassemblyEntry?: boolean;
  /**
   * 本页当前是否显示。`/devices` 系列是常驻槽位：切到别的栏目只是被隐藏、不卸载（模型与进度都留着），
   * 但隐藏期间不该继续推进自动拆解演示。默认 true，便于测试单独渲染本页。
   */
  active?: boolean;
}

function DeviceExplorer({
  device,
  devices,
  hasSite,
  SceneComponent,
  supportsWebGL,
  disassemblyEntry,
  active,
}: {
  device: DeviceConfig;
  devices: DeviceConfig[];
  hasSite: boolean;
  SceneComponent: DeviceSceneComponent;
  supportsWebGL: () => boolean;
  disassemblyEntry: boolean;
  active: boolean;
}) {
  const navigate = useNavigate();
  const location = useLocation();
  /* 从三维场地（`/site`）点标记下钻来的：那枚「返回场地模型」就是"退回上一页"，
     用 `navigate(-1)` —— 与浏览器返回键同义，也不新增历史（场地 ⇄ 设备不会两地打转）。 */
  const cameFromSite = useCameFrom('/site');
  const backToSite = useCallback(() => {
    if (cameFromSite) { navigate(-1); return; }
    // 从设备索引/深链进来的：显式去三维场地；深链那条历史用 replace 顶掉，免得返回键直接退出站点。
    navigate('/site', { replace: location.key === 'default' });
  }, [cameFromSite, location.key, navigate]);
  const [state, dispatch] = useReducer(deviceExplorerReducer, device, item => createDeviceExplorerState(item, disassemblyEntry));
  const [query, setQuery] = useState('');
  const [deviceMenuOpen, setDeviceMenuOpen] = useState(false);
  const [resourceScope, setResourceScope] = useState<'device' | 'part' | null>(null);
  const [hoveredPartId, setHoveredPartId] = useState<string | null>(null);
  const [partsCollapsed, setPartsCollapsed] = useState(false);
  const partsPanelRef = useRef<HTMLElement>(null);
  const expandedHeightRef = useRef(0);
  const partsDragRef = useRef<{
    pointerId: number;
    startX: number;
    startY: number;
    left: number;
    top: number;
    width: number;
    height: number;
    moved: boolean;
  } | null>(null);
  const tooltipRef = useRef<HTMLDivElement>(null);
  // 「全屏查看」按钮的宿主元素：全屏状态与能力都挂在它身上（见 `useFullscreen`）。
  const studioRef = useRef<HTMLDivElement>(null);
  const fullscreen = useFullscreen(studioRef);
  const [webglAvailable] = useState(() => supportsWebGL());
  // 真实 FBX 交付件未必带语义化节点名（例如 2250kV 变压器是 59 个编号网格），
  // 这时没有可拆解部件——整机查看，拆解相关的入口整体隐藏。
  const hasParts = device.parts.length > 0;
  // 没有挂资料的设备（例如目录里只有模型、还没交资料的 5400kV 发生器）不显示资料入口，
  // 避免点开一个空抽屉。
  const hasResources = device.resourceIds.length > 0;
  const selectedPart = device.parts.find(part => part.id === state.selectedPartId);
  const hoveredPart = device.parts.find(part => part.id === hoveredPartId);
  const filteredParts = useMemo(() => {
    const term = query.trim().toLowerCase();
    return device.parts.filter(part => !term
      || part.label.toLowerCase().includes(term)
      || part.id.toLowerCase().includes(term)
      || part.nodeNames.some(name => name.toLowerCase().includes(term)));
  }, [device.parts, query]);
  const drawerPart = resourceScope === 'part' ? selectedPart : undefined;
  // 部件序号：目录里的行号 == 模型上编号牌的号码（拆解次序与目录次序一致，用户不用猜）。
  const partNumbers = useMemo(() => {
    const map = new Map<string, number>();
    device.parts.forEach((part, index) => map.set(part.id, index + 1));
    return map;
  }, [device.parts]);
  const resourceLabel = drawerPart?.label ?? device.name;
  const resourceIds = drawerPart?.resourceIds ?? device.resourceIds;

  const selectPart = useCallback((partId: string) => dispatch({ type: 'select-part', partId }), []);
  const handlePartHover = useCallback((id: string | null) => setHoveredPartId(id), []);
  // resourceLabel 随选择变化；用 ref 保持 openResource 的引用稳定（memo Scene 的 props 之一）。
  const resourceLabelRef = useRef(resourceLabel);
  resourceLabelRef.current = resourceLabel;
  const openResource = useCallback((id: string) => navigate(`/archive/${id}`, {
    state: { pathname: disassemblyEntry ? `/devices/${device.id}/disassembly` : `/devices/${device.id}`, label: resourceLabelRef.current },
  }), [navigate, disassemblyEntry, device.id]);
  const moveTooltip = (event: React.PointerEvent) => {
    if (!tooltipRef.current) return;
    tooltipRef.current.style.left = `${event.clientX}px`;
    tooltipRef.current.style.top = `${event.clientY}px`;
  };

  // --- 部件层级面板：可拖动浮窗 + 可收缩标题栏 ---
  const partsFrozenRef = useRef(false);
  const freezePartsPanel = () => {
    const panel = partsPanelRef.current;
    const studio = panel?.offsetParent as HTMLElement | null;
    if (!panel || !studio) return;
    const panelRect = panel.getBoundingClientRect();
    const studioRect = studio.getBoundingClientRect();
    panel.style.left = `${panelRect.left - studioRect.left}px`;
    panel.style.top = `${panelRect.top - studioRect.top}px`;
    panel.style.width = `${panelRect.width}px`;
    panel.style.height = `${panelRect.height}px`;
    panel.style.right = 'auto';
    panel.style.bottom = 'auto';
  };
  const startPartsDrag = (event: React.PointerEvent<HTMLElement>) => {
    if (event.button !== 0 && event.pointerType === 'mouse') return;
    const target = event.target as HTMLElement;
    if (target.closest('button')) return;
    const panel = partsPanelRef.current;
    const studio = panel?.offsetParent as HTMLElement | null;
    if (!panel || !studio) return;
    const panelRect = panel.getBoundingClientRect();
    const studioRect = studio.getBoundingClientRect();
    partsDragRef.current = {
      pointerId: event.pointerId,
      startX: event.clientX,
      startY: event.clientY,
      left: panelRect.left - studioRect.left,
      top: panelRect.top - studioRect.top,
      width: panelRect.width,
      height: panelRect.height,
      moved: false,
    };
    event.currentTarget.setPointerCapture?.(event.pointerId);
    panel.classList.add('is-dragging');
  };
  const movePartsDrag = (event: React.PointerEvent<HTMLElement>) => {
    const drag = partsDragRef.current;
    const panel = partsPanelRef.current;
    if (!drag || !panel || drag.pointerId !== event.pointerId) return;
    if (Math.abs(event.clientX - drag.startX) > 2 || Math.abs(event.clientY - drag.startY) > 2) drag.moved = true;
    if (!drag.moved) return;
    if (!partsFrozenRef.current) {
      partsFrozenRef.current = true;
      freezePartsPanel();
    }
    const studio = panel.offsetParent as HTMLElement | null;
    if (!studio) return;
    const studioRect = studio.getBoundingClientRect();
    const maxX = Math.max(0, studioRect.width - drag.width - 8);
    const maxY = Math.max(0, studioRect.height - drag.height - 8);
    const left = Math.min(maxX, Math.max(8, drag.left + event.clientX - drag.startX));
    const top = Math.min(maxY, Math.max(8, drag.top + event.clientY - drag.startY));
    panel.style.left = `${left}px`;
    panel.style.top = `${top}px`;
  };
  const endPartsDrag = (event: React.PointerEvent<HTMLElement>) => {
    const drag = partsDragRef.current;
    if (!drag || drag.pointerId !== event.pointerId) return;
    const tappedWithoutMove = !drag.moved;
    partsDragRef.current = null;
    const panel = partsPanelRef.current;
    panel?.classList.remove('is-dragging');
    event.currentTarget.releasePointerCapture?.(event.pointerId);
    // 收缩为标题栏后，轻点标题栏即可再次展开
    if (tappedWithoutMove && partsCollapsed) {
      const target = event.target as HTMLElement;
      if (!target.closest('button')) togglePartsCollapse();
    }
  };
  const expandPartsPanel = () => {
    const panel = partsPanelRef.current;
    if (!panel) return;
    if (partsFrozenRef.current) {
      const height = expandedHeightRef.current;
      if (height > 0) panel.style.height = `${height}px`;
      else panel.style.removeProperty('height');
    }
    setPartsCollapsed(false);
  };
  const collapsePartsPanel = () => {
    const panel = partsPanelRef.current;
    if (!panel) return;
    const header = panel.querySelector('header');
    const headerHeight = header?.offsetHeight ?? 48;
    if (!partsFrozenRef.current) {
      partsFrozenRef.current = true;
      freezePartsPanel();
    }
    expandedHeightRef.current = panel.offsetHeight;
    panel.style.height = `${Math.max(headerHeight, 48)}px`;
    setPartsCollapsed(true);
  };
  const togglePartsCollapse = () => {
    if (partsCollapsed) expandPartsPanel();
    else collapsePartsPanel();
  };
  const openPartsPanel = () => {
    if (state.panel !== 'parts') {
      if (partsCollapsed) expandPartsPanel();
    }
    dispatch({ type: 'open-panel', panel: 'parts' });
  };

  // 自动拆解演示：按节流节奏推进拆解进度，到 100% 后自动停止（单程）。
  // 动画视觉由 DeviceScene 的时间阻尼负责；React 侧只需 ~6.7Hz 回写，
  // 避免高频 dispatch 重渲染。标签页不可见时暂停，避免后台空转。
  useEffect(() => {
    if (!state.autoExplode) return;
    const timer = window.setInterval(() => {
      // 本页被槽位隐藏时（切到别的栏目）不再推进：渲染循环已经停了，这里也要停，
      // 别在看不见的页面里把单程演示跑完。
      if (!active) return;
      dispatch({ type: 'advance-auto-explode' });
    }, 150);
    const pauseWhenHidden = () => {
      if (document.hidden) dispatch({ type: 'stop-auto-explode' });
    };
    document.addEventListener('visibilitychange', pauseWhenHidden);
    return () => {
      window.clearInterval(timer);
      document.removeEventListener('visibilitychange', pauseWhenHidden);
    };
  }, [state.autoExplode, dispatch, active]);

  return (
    <section className={`device-explorer${deviceMenuOpen ? ' is-choosing-device' : ''}`}>
      <div ref={studioRef} className={`device-studio${state.disassemblyEntry && state.panel === 'parts' ? ' keeps-dock' : ''}`} onPointerMove={moveTooltip}>
        {webglAvailable ? (
          <SceneComponent
            device={device}
            state={state}
            onPartSelect={selectPart}
            onPartHover={handlePartHover}
          />
        ) : (
          <div className="device-webgl-fallback">
            <img src={resolveAssetUrl(device.poster)} alt={`${device.name}静态预览`} />
            <strong>三维查看暂不可用</strong>
            <p>仍可通过部件目录阅读说明并打开关联资料。</p>
          </div>
        )}
        {/*
          头部一行：左边是身份（标题 + 角标 + 切换按钮 + 一行副标题），右边是工具圆钮。
          两者都在同一个固定高度的 flex 行里垂直居中 —— 从前它们各自绝对定位、各写各的 top，
          实测 3D 角标、标题和右上角圆钮会差几个像素，看着就是"没对齐"。
        */}
        <div className="device-header">
          <header className="device-identity">
            <div className="device-title-row">
              {/* 2026-10-19（现场第四轮 UI 审查 ④）：这个键叫「返回场地模型」，去的却是 `/devices`
                  —— 那是**设备索引**（precision 把旧 UI 的「设备模型」页拆成了 `/devices` 索引 + `/site` 三维场地），
                  于是它实际把用户送回设备列表、而不是他来的那块场地，场地标记 → 设备页 → 回场地的闭环在这里断掉。
                  改成 `/site`：与场地上「点标记直接进设备」互为回路。
                  2026-10-15（层级返回逻辑）：目标再按来路分两种——从场地页点标记下钻进来的是"退回上一页"
                  （`navigate(-1)`，不新增历史、不与场地页打转）；从设备索引或深链进来时才显式去 `/site`。
                  2026-10-19（现场要求）：这枚键从右上角工具组挪到**设备名左侧**——它退的是一层层级，
                  位置就该在标题前面，右上角只留搜索与资料。 */}
              {hasSite && <button type="button" aria-label="返回场地模型" title="返回场地模型" onClick={backToSite}><ChevronLeft /></button>}
              {/* `title` 是给窄屏兜底的：precision 把它做成一行胶囊后，手机 390px 上
                  长设备名会被省略号截断（右侧还有切换键 + 两枚工具键），悬停时可读全文。 */}
              <h1 title={device.name}>{device.name}</h1><b>3D</b>
              <button type="button" aria-haspopup="listbox" aria-expanded={deviceMenuOpen} aria-label={`切换设备（当前 ${device.name}）`} onClick={() => setDeviceMenuOpen(open => !open)}><ChevronDown /></button>
            </div>
            {/* 副标题只留署名：`N 个可识别部件` / `整机查看` 这类旁白已按现场要求去掉
                （部件数量在部件面板里本来就有）。 */}
            <p>数字博物馆</p>
            {deviceMenuOpen && (
              <div className="device-choice-menu" role="listbox" aria-label="选择设备">
                {/* 换设备是"同一页换内容"，不是往下钻一层：`replace` 不堆历史，
                    并把来路标记原样带走，换了设备之后那枚「返回场地模型」的判据仍然成立。 */}
                {devices.map(item => <button type="button" role="option" aria-selected={item.id === device.id} key={item.id} onClick={() => { setDeviceMenuOpen(false); navigate(`/devices/${item.id}`, { replace: true, state: location.state }); }}>{item.name}</button>)}
              </div>
            )}
          </header>

          <nav className="device-top-actions" aria-label="设备工具">
            {/* 「返回场地模型」已挪到设备名左侧（`.device-title-row`）：层级返回属于标题，不属于工具组。 */}
            {hasParts && <button type="button" className={state.panel === 'search' ? 'is-active' : ''} aria-label="搜索部件" aria-pressed={state.panel === 'search'} onClick={() => dispatch({ type: 'open-panel', panel: 'search' })}><Search /></button>}
            {hasResources && <button type="button" aria-label={`查看${device.name}资料`} onClick={() => setResourceScope('device')}><BookOpen /></button>}
          </nav>
        </div>

        {hasParts && state.panel === 'search' && (
          <section className="device-search-panel" aria-label="查找设备部件">
            <header><span>查找部件</span><button type="button" aria-label="关闭搜索" onClick={() => dispatch({ type: 'close-panel' })}><X /></button></header>
            <label><Search /><input autoFocus type="search" value={query} onChange={event => setQuery(event.target.value)} placeholder="名称、编号或模型节点" aria-label="搜索设备部件" /></label>
            <div>{filteredParts.map(part => <button type="button" key={part.id} onClick={() => selectPart(part.id)}><span>{part.label}</span><small>{part.id}</small><ChevronRight /></button>)}</div>
            {filteredParts.length === 0 && <p>没有匹配的部件。</p>}
          </section>
        )}

        {hasParts && (
        <section ref={partsPanelRef} className={`device-parts-panel ${state.panel === 'parts' ? 'is-open' : ''}${partsCollapsed ? ' is-collapsed' : ''}`} aria-label="设备部件">
          <header
            onPointerDown={startPartsDrag}
            onPointerMove={movePartsDrag}
            onPointerUp={endPartsDrag}
            onPointerCancel={endPartsDrag}
            title={partsCollapsed ? '点击展开部件层级面板' : '拖动标题可移动面板'}
          >
            <GripVertical className="device-parts-grip" aria-hidden="true" />
            <span>部件层级</span><small>{device.parts.length}</small>
            <button type="button" className="device-parts-collapse" aria-label={partsCollapsed ? '展开部件层级面板' : '收起部件层级面板'} aria-expanded={!partsCollapsed} onClick={togglePartsCollapse}>{partsCollapsed ? <ChevronUp /> : <ChevronDown />}</button>
            <button type="button" className="device-parts-close" aria-label="关闭部件面板" onClick={() => dispatch({ type: 'close-panel' })}><X /></button>
          </header>
          <label className="device-part-filter"><Search /><input type="search" value={query} onChange={event => setQuery(event.target.value)} placeholder="筛选部件" aria-label="筛选部件目录" /></label>
          <div className="device-part-list">
            {filteredParts.map(part => {
              const hidden = state.hiddenPartIds.includes(part.id);
              return (
                <div className={`device-part-row${hidden ? ' is-hidden' : ''}`} key={part.id} onMouseEnter={() => setHoveredPartId(part.id)} onMouseLeave={() => setHoveredPartId(null)}>
                  <button type="button" className="device-part-select" aria-label={part.label} aria-pressed={part.id === state.selectedPartId} data-hovered={part.id === hoveredPartId} onClick={() => selectPart(part.id)}>
                    <i className="device-part-dot">{partNumbers.get(part.id) ?? ''}</i><span>{part.label}</span><small>{part.id}</small>
                  </button>
                  <button
                    type="button"
                    className="device-part-visibility"
                    aria-label={hidden ? `显示${part.label}` : `隐藏${part.label}`}
                    aria-pressed={!hidden}
                    title={hidden ? '显示该部件' : '隐藏该部件'}
                    onClick={() => dispatch({ type: 'toggle-part-visibility', partId: part.id })}
                  >
                    {hidden ? <EyeOff /> : <Eye />}
                  </button>
                </div>
              );
            })}
            {filteredParts.length === 0 && <p>没有匹配的部件</p>}
          </div>
          <footer>
            <span>{state.hiddenPartIds.length ? `已隐藏 ${state.hiddenPartIds.length} / ${device.parts.length}` : `共 ${device.parts.length} 个部件`}</span>
            {state.hiddenPartIds.length > 0
              ? <button type="button" onClick={() => dispatch({ type: 'show-all-parts' })}>全部显示</button>
              : hasResources && <button type="button" onClick={() => setResourceScope('device')}>整机资料</button>}
          </footer>
        </section>
        )}

        <nav className="device-view-controls" aria-label="模型视角">
          {VIEWS.map(view => <button type="button" key={view.id} aria-label={view.label} aria-pressed={state.view === view.id} className={state.view === view.id ? 'is-active' : ''} onClick={() => dispatch({ type: 'set-view', view: view.id })}>{view.short}</button>)}
          <i aria-hidden="true" />
          <button type="button" aria-label={state.rotate ? '暂停自动旋转' : '自动旋转'} aria-pressed={state.rotate} className={state.rotate ? 'is-active' : ''} onClick={() => dispatch({ type: 'toggle-rotate' })}>{state.rotate ? <Pause /> : <RotateCw />}</button>
          {fullscreen.supported && <button type="button" aria-label={fullscreen.active ? '退出全屏' : '全屏查看'} aria-pressed={fullscreen.active} onClick={fullscreen.toggle}>{fullscreen.active ? <Minimize /> : <Maximize />}</button>}
          <button type="button" aria-label="复位模型" onClick={() => dispatch({ type: 'reset' })}><RotateCcw /></button>
        </nav>

        {/* 只在有状态可说时出现：隔离/拆解是用户动作的结果，值得回显；
            "三维模型 · 整机查看"这类默认态属于噪音，不再常驻。 */}
        {(state.isolatedPartId || state.explode > 0.05) && (
          <div className="device-caption" aria-live="polite"><span />{state.isolatedPartId ? `已隔离 · ${selectedPart?.label ?? ''}` : '设备结构 · 分离展示'}<span /></div>
        )}

        {hasParts && (
        <div className="device-explode-dock">
          <button type="button" className="device-parts-trigger" aria-label="打开部件面板" onClick={openPartsPanel}><Layers3 /><span>部件</span></button>
          <button type="button" className={`device-auto-explode${state.autoExplode ? ' is-active' : ''}`} aria-label={state.autoExplode ? '暂停自动拆解' : '自动拆解'} aria-pressed={state.autoExplode} onClick={() => dispatch({ type: state.autoExplode ? 'stop-auto-explode' : 'start-auto-explode' })}>{state.autoExplode ? <Pause /> : <Play />}<span>{state.autoExplode ? '暂停' : '自动'}</span></button>
          <label>
            <span>拆解设备 <output>{Math.round(state.explode * 100)}%</output></span>
            <input type="range" min="0" max="100" step="1" value={Math.round(state.explode * 100)} aria-label="拆解进度" onChange={event => dispatch({ type: 'set-explode', value: Number(event.target.value) / 100 })} />
            <small><span>整机</span><span>分离部件</span></small>
          </label>
          <button type="button" aria-label="组合并复位" onClick={() => dispatch({ type: 'reset' })}><RotateCcw /><span>复位</span></button>
        </div>
        )}

        {hasResources && (
          <footer className="device-footer">
            <button type="button" onClick={() => setResourceScope('device')}>整机资料 <BookOpen /></button>
          </footer>
        )}

        {hoveredPart && <div ref={tooltipRef} className="device-part-tooltip" role="tooltip">{hoveredPart.label}</div>}

        {selectedPart && state.detailsOpen && (
          <aside className={`device-detail-sheet ${state.isolatedPartId ? 'is-isolated' : ''}`} role="dialog" aria-label={`${selectedPart.label}详情`}>
            <button type="button" className="device-detail-close" aria-label="关闭部件详情" onClick={() => dispatch({ type: 'close-details' })}><X /></button>
            <header><i className="device-part-dot" /><h2>{selectedPart.label}</h2></header>
            <div className="device-detail-scroll">
              {/* 部件说明优先；配置里没有说明时不再回落到设备简介（那是内部说明，不该出现在展项上） */}
              {(selectedPart.description || device.summary).trim() && <p>{selectedPart.description || device.summary}</p>}
              <dl><div><dt>部件编号</dt><dd>{selectedPart.id}</dd></div>{selectedPart.resourceIds.length > 0 && <div><dt>关联资料</dt><dd>{selectedPart.resourceIds.length}</dd></div>}</dl>
            </div>
            <div className="device-detail-actions">
              <button type="button" className="primary" aria-label={state.isolatedPartId ? '恢复整机' : `隔离${selectedPart.label}`} onClick={() => dispatch({ type: 'toggle-isolate' })}><Focus />{state.isolatedPartId ? '恢复整机' : '隔离部件'}<ChevronRight /></button>
              {selectedPart.resourceIds.length > 0 && <button type="button" aria-label={`查看${selectedPart.label}资料`} onClick={() => setResourceScope('part')}><BookOpen />查看关联资料</button>}
              <button type="button" onClick={() => dispatch({ type: 'clear-selection' })}>清除选择</button>
            </div>
          </aside>
        )}
      </div>

      {resourceScope && <ResourceDrawer resourceIds={resourceIds} originLabel={resourceLabel} onOpen={openResource} onClose={() => setResourceScope(null)} />}
    </section>
  );
}

export function DevicePage({ SceneComponent = DeviceScene, supportsWebGL = hasWebGLSupport, disassemblyEntry = false, active = true }: DevicePageProps) {
  const { deviceId } = useParams();
  const { config, repository } = useMuseumConfig();
  const device = repository.getDevice(deviceId ?? '') ?? config.devices[0];
  if (!device) return <section className="status-panel" role="alert">没有可用的设备配置</section>;
  return <DeviceExplorer key={`${device.id}:${disassemblyEntry}`} device={device} devices={config.devices} hasSite={Boolean(config.siteModel)} SceneComponent={SceneComponent} supportsWebGL={supportsWebGL} disassemblyEntry={disassemblyEntry} active={active} />;
}

export default DevicePage;
