import type { DeviceConfig } from '../../config/schema';

export type DeviceExplorerView = 'three-quarter' | 'front' | 'side' | 'back';

export interface DeviceExplorerState {
  selectedPartId: string | null;
  isolatedPartId: string | null;
  /** 被单独隐藏的部件（默认空 = 全部显示）。 */
  hiddenPartIds: string[];
  explode: number;
  autoExplode: boolean;
  view: DeviceExplorerView;
  rotate: boolean;
  reset: number;
  panel: 'parts' | 'search' | null;
  detailsOpen: boolean;
  disassemblyEntry: boolean;
}

export type DeviceExplorerAction =
  | { type: 'select-part'; partId: string }
  | { type: 'clear-selection' }
  | { type: 'toggle-isolate' }
  | { type: 'toggle-part-visibility'; partId: string }
  | { type: 'show-all-parts' }
  | { type: 'set-explode'; value: number }
  | { type: 'start-auto-explode' }
  | { type: 'stop-auto-explode' }
  | { type: 'advance-auto-explode' }
  | { type: 'set-view'; view: DeviceExplorerView }
  | { type: 'toggle-rotate' }
  | { type: 'reset' }
  | { type: 'open-panel'; panel: 'parts' | 'search' }
  | { type: 'close-panel' }
  | { type: 'close-details' };

/**
 * 自动拆解演示每次步进的拆解量（0–1）。配合 DevicePage 中的 ~150ms
 * 节流驱动，单程约 4.5 秒；动画平滑仍由 DeviceScene 的时间阻尼负责，
 * React 侧只做低频进度回写。
 */
export const AUTO_EXPLODE_STEP = 0.035;

export function createDeviceExplorerState(_device: DeviceConfig, disassemblyEntry = false): DeviceExplorerState {
  return {
    selectedPartId: null,
    isolatedPartId: null,
    hiddenPartIds: [],
    explode: 0,
    autoExplode: false,
    view: 'three-quarter',
    rotate: false,
    reset: 0,
    panel: disassemblyEntry ? 'parts' : null,
    detailsOpen: false,
    disassemblyEntry,
  };
}

export function deviceExplorerReducer(state: DeviceExplorerState, action: DeviceExplorerAction): DeviceExplorerState {
  switch (action.type) {
    case 'select-part':
      return { ...state, selectedPartId: action.partId, isolatedPartId: null, rotate: false, autoExplode: false, detailsOpen: true, panel: null };
    case 'clear-selection':
      return { ...state, selectedPartId: null, isolatedPartId: null, autoExplode: false, detailsOpen: false };
    case 'toggle-isolate':
      if (!state.selectedPartId) return state;
      return { ...state, isolatedPartId: state.isolatedPartId ? null : state.selectedPartId, explode: 0, autoExplode: false, rotate: false };
    case 'toggle-part-visibility':
      return {
        ...state,
        hiddenPartIds: state.hiddenPartIds.includes(action.partId)
          ? state.hiddenPartIds.filter(id => id !== action.partId)
          : [...state.hiddenPartIds, action.partId],
      };
    case 'show-all-parts':
      return state.hiddenPartIds.length ? { ...state, hiddenPartIds: [] } : state;
    case 'set-explode':
      return { ...state, explode: Math.min(1, Math.max(0, action.value)), isolatedPartId: null, autoExplode: false, rotate: false };
    case 'start-auto-explode': {
      // 单程演示：若已拆解到顶，重按播放从整机重新开始；否则从当前位置继续拆到顶。
      const fromScratch = state.explode >= 1 - AUTO_EXPLODE_STEP;
      return { ...state, autoExplode: true, isolatedPartId: null, explode: fromScratch ? 0 : state.explode, rotate: false };
    }
    case 'stop-auto-explode':
      return { ...state, autoExplode: false };
    case 'advance-auto-explode': {
      if (!state.autoExplode) return state;
      const next = Math.min(1, state.explode + AUTO_EXPLODE_STEP);
      return { ...state, explode: next, autoExplode: next < 1 };
    }
    case 'set-view':
      return { ...state, view: action.view, rotate: false, autoExplode: false, reset: state.reset + 1 };
    case 'toggle-rotate':
      return { ...state, rotate: !state.rotate };
    case 'reset':
      return {
        ...state,
        selectedPartId: null,
        isolatedPartId: null,
        hiddenPartIds: [],
        explode: 0,
        autoExplode: false,
        view: 'three-quarter',
        rotate: false,
        reset: state.reset + 1,
        panel: null,
        detailsOpen: false,
      };
    case 'open-panel':
      return { ...state, panel: state.panel === action.panel ? null : action.panel, detailsOpen: false };
    case 'close-panel':
      return { ...state, panel: null };
    case 'close-details':
      return { ...state, detailsOpen: false };
  }
}
