import { FileText, X } from 'lucide-react';
import { useEffect, useMemo, useRef, useState } from 'react';
import { useMuseumConfig } from '../../config/ConfigProvider';
import { resolveAssetUrl } from '../../config/loadConfig';
import type { ResourceConfig } from '../../config/schema';
import { prefetchResourceViewer } from '../../shared/prefetch';
import { cardVisual, groupResources, kindOptions, resourceBadge, splitTitle } from './resourceGroups';
import './archive.css';

export function ResourceDrawer({ resourceIds, originLabel, onOpen, onClose: closeDrawer }: {
  resourceIds: string[];
  originLabel: string;
  onOpen(id: string): void;
  onClose(): void;
}) {
  const { repository } = useMuseumConfig();
  const resources = repository.getResources(resourceIds);
  const [kind, setKind] = useState<ResourceConfig['kind'] | 'all'>('all');
  const options = useMemo(() => kindOptions(resources), [resources]);
  const filtered = useMemo(() => (kind === 'all' ? resources : resources.filter(item => item.kind === kind)), [resources, kind]);
  // 一类一组排好：图片 → 图纸（PDF 文档）→ 视频 → 模型，组内按年代升序。
  const groups = useMemo(() => groupResources(filtered), [filtered]);
  const openerRef = useRef<HTMLElement | null>(document.activeElement instanceof HTMLElement ? document.activeElement : null);
  const handleClose = () => {
    openerRef.current?.focus();
    closeDrawer();
  };
  const onClose = handleClose;
  useEffect(() => {
    const dialog = document.querySelector<HTMLElement>('.resource-drawer');
    if (!dialog) return;
    dialog.querySelector<HTMLButtonElement>('header button')?.focus();
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        event.preventDefault();
        handleClose();
        return;
      }
      if (event.key !== 'Tab') return;
      const focusable = [...dialog.querySelectorAll<HTMLElement>('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])')].filter(element => !element.hasAttribute('disabled'));
      if (!focusable.length) return;
      const first = focusable[0]!;
      const last = focusable[focusable.length - 1]!;
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
      }
    };
    dialog.addEventListener('keydown', handleKeyDown);
    return () => dialog.removeEventListener('keydown', handleKeyDown);
  }, []);
  const showGroupHeaders = groups.length > 1;
  return (
    <div className="drawer-backdrop" role="presentation" onClick={handleClose}>
      <section className="resource-drawer" role="dialog" aria-modal="true" aria-label={`${originLabel}相关资料`} onClick={event => event.stopPropagation()}>
        <header><div><small className="eyebrow">关联对象</small><h2>{originLabel}</h2></div><button type="button" aria-label="关闭资料" onClick={onClose}><X /></button></header>
        {resources.length > 1 && (
          <div className="archive-facet-row resource-drawer-filters" aria-label="资料类型">
            {options.map(option => (
              <button type="button" key={option.value} aria-pressed={kind === option.value} className={kind === option.value ? 'is-active' : undefined} onClick={() => setKind(option.value)}>{option.label}</button>
            ))}
          </div>
        )}
        {resources.length === 0 && <p className="resource-empty">暂无关联资料</p>}
        {resources.length > 0 && filtered.length === 0 && <p className="resource-empty">没有这个类型的资料</p>}
        {groups.map(group => (
          <section className="resource-group" key={group.key} aria-label={showGroupHeaders ? group.label : undefined}>
            {showGroupHeaders && <header><strong>{group.label}</strong><span>{group.items.length} 项</span></header>}
            <div className="resource-list">
              {group.items.map(item => {
                const visual = cardVisual(item);
                const badge = resourceBadge(item);
                const title = splitTitle(item.title);
                return (
                  <button type="button" key={item.id} onPointerEnter={() => prefetchResourceViewer(item.kind)} onFocus={() => prefetchResourceViewer(item.kind)} onClick={() => onOpen(item.id)} aria-label={`打开${item.title}`}>
                    {visual.thumb
                      ? <span className="resource-thumb"><img src={resolveAssetUrl(visual.thumb)} alt="" loading="lazy" decoding="async" /></span>
                      : <span className="resource-thumb is-paper"><FileText /></span>}
                    <span className="resource-row-main">
                      <strong>{title.main}{title.suffix && <span className="archive-year">{title.suffix}</span>}</strong>
                      <span className="resource-row-meta">
                        {[badge.kind, badge.measure].filter(Boolean).join(' · ')}
                        {badge.scope && <span className="resource-scope">{badge.scope}</span>}
                      </span>
                    </span>
                  </button>
                );
              })}
            </div>
          </section>
        ))}
      </section>
    </div>
  );
}
